export type Category = 'Software Development' | 'Data & AI' | 'Cybersecurity' | 'Cloud & DevOps' | 'Systems & Data' | 'Design & Product' | 'Testing'
export type Difficulty = 'Beginner' | 'Intermediate' | 'Advanced'
export type ResourceType = 'Course' | 'Docs' | 'Practice' | 'Video' | 'Book'

export type Resource = {
  title: string
  type: ResourceType
  provider: string
  url: string
  description: string
  isFree: boolean
  difficulty: Difficulty
}

export type Project = {
  id: string
  title: string
  level: Difficulty
  difficulty: Difficulty
  estimatedTime: string
  description: string
  problemStatement: string
  technologies: string[]
  skills: string[]
  features: string[]
  learningOutcomes: string[]
  suggestedDataset: string
  deliverables: string[]
  advancedExtensions: string[]
  tags: string[]
}

export type Stage = {
  id: string
  order: number
  title: string
  kicker: string
  subtitle: string
  description: string
  time: string
  estimatedTime: string
  difficulty: Difficulty
  prerequisites: string[]
  skills: string[]
  technologies: string[]
  topics: string[]
  outcomes: string[]
  resources: Resource[]
  projects: Project[]
}

export type Role = {
  title: string
  slug: string
  category: Category
  difficulty: Difficulty
  description: string
  accent: string
  estimatedTime: string
  prerequisites: string[]
  technologies: string[]
  learningOrder: string[]
  careerProgression: string[]
  skills: { group: string; items: string[] }[]
  stages: Stage[]
  projects: Project[]
}

