  'Automation Test Engineer': { category: 'Testing', difficulty: 'Intermediate', time: '5–8 months', technologies: ['Playwright or Selenium', 'TypeScript', 'Python', 'Docker', 'CI/CD'], career: ['Automation Test Engineer', 'Senior SDET', 'Quality Architect', 'Engineering Lead'], prerequisites: ['Programming basics', 'Testing fundamentals', 'Git workflows'] },
  'UI/UX Designer': { category: 'Design & Product', difficulty: 'Beginner', time: '4–6 months', technologies: ['Figma', 'FigJam', 'Notion', 'Webflow'], career: ['UI/UX Designer', 'Senior Product Designer', 'Design Lead', 'Design Director'], prerequisites: ['Curiosity about people', 'Visual observation', 'Willingness to critique and iterate'] },
  'Product Designer': { category: 'Design & Product', difficulty: 'Intermediate', time: '6–9 months', technologies: ['Figma', 'FigJam', 'Maze', 'Storybook', 'Analytics'], career: ['Product Designer', 'Senior Product Designer', 'Design Lead', 'Head of Design'], prerequisites: ['UX fundamentals', 'Visual design basics', 'Interest in product outcomes'] },
  'Product Manager': { category: 'Design & Product', difficulty: 'Intermediate', time: '5–8 months', technologies: ['Notion', 'Linear', 'Jira', 'SQL', 'Amplitude'], career: ['Product Manager', 'Senior Product Manager', 'Group Product Manager', 'Product Director'], prerequisites: ['Clear writing', 'Empathy for users', 'Comfort making decisions with incomplete information'] },
